using System;using System.Drawing;using System.IO;using System.Linq;using System.Reflection;using System.Threading;using System.Windows.Forms;
namespace Frociart.Tests {internal static class LivePseudocodeTests {
 static int checks;const BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public;
 static T Field<T>(object obj,string name){return(T)obj.GetType().GetField(name,F).GetValue(obj);}
 static object Call(object obj,string name,params object[] args){return obj.GetType().GetMethod(name,F).Invoke(obj,args);}
 static void Check(bool ok,string why){if(!ok)throw new Exception(why);checks++;Console.WriteLine("PASS "+why);}
 static void Pump(int ms=300){var until=DateTime.UtcNow.AddMilliseconds(ms);do{Application.DoEvents();Thread.Sleep(3);}while(DateTime.UtcNow<until);}
 static string Bytes(Diagram d){return Convert.ToBase64String(DiagramIO.EncodeDocument(d));}
 [STAThread]static int Main(){try{Application.EnableVisualStyles();Ui.SetSeparateIo(false,false);using(var f=new MainForm(null,true)){
 f.ShowInTaskbar=false;f.StartPosition=FormStartPosition.Manual;f.Location=new Point(-3000,-3000);f.Size=new Size(1420,900);f.Show();Pump();f.EnterEditor();f.SetWorkspaceLayout(1,false);
 var doc=FlowPseudocode.Decode("LEGGI x\nSTAMPA \"Valore: \" + x");f.SetDocument(doc,null,false);Pump();var preview=Field<PseudocodePreview>(f,"livePseudocode");Console.WriteLine("PREVIEW visible="+preview.Visible+" readOnly="+preview.Code.ReadOnly+" parent="+preview.Parent.Visible+" editor="+Field<TableLayoutPanel>(f,"editorBody").Visible);Check(preview.Visible&&preview.Code.ReadOnly,"Live read-only panel visible in editor");Check(preview.Code.Text.Contains("LEGGI x")&&preview.Code.Text.Contains("STAMPA \"Valore: \" + x"),"Initial diagram appears automatically");
 var n=doc.Nodes.Single(node=>node.Kind==NodeKind.Output);f.Canvas.SelectNode(n.Id);Pump();string original=Bytes(doc);var text=Field<TextBox>(f,"expression");text.Text="stampa x + 1";Pump();Check(preview.Code.Text.Contains("STAMPA x + 1"),"Unapplied text updates live pseudocode");Check(Bytes(doc)==original,"Preview does not commit draft or alter source");
 text.Text="stampa \"";Pump();Check(preview.Code.Text.Length==0&&!Field<FlowButton>(preview,"copy").Enabled,"Incomplete expression never shows stale code as current");Check(preview.State.Text.Contains("Blocco"),"Inline conversion error identifies block");text.Text="stampa x";Pump();Check(preview.Code.Text.Contains("STAMPA x"),"Valid text recovers automatically");f.CommitInspector();Pump();Check(preview.Code.Text.Contains("STAMPA x"),"Commit retains current preview");Call(f,"Undo");Pump();Check(preview.Code.Text.Contains("STAMPA \"Valore: \" + x"),"Undo updates pseudocode");Call(f,"Redo");Pump();Check(preview.Code.Text.Contains("STAMPA x"),"Redo updates pseudocode");
 int generated=preview.Generations;for(int i=0;i<40;i++){f.Document.Nodes[0].X++;Call(f,"MarkDirty");}Pump();Check(preview.Generations==generated,"Moving blocks does not regenerate unchanged algorithm");Check(!Field<System.Windows.Forms.Timer>(preview,"timer").Enabled,"Preview timer stops at rest");
 f.Document.Edges.RemoveAt(0);Call(f,"MarkDirty");Pump();Check(preview.Code.Text.Contains("SCOLLEGATO"),"Disconnecting an arrow updates code");f.SetDocument(FlowPseudocode.Decode("STAMPA \"Nuovo\""),null,false);Pump();Check(preview.Code.Text.Contains("Nuovo")&&!preview.Code.Text.Contains("LEGGI x"),"Switching project removes old preview");
 foreach(bool dark in new[]{true,false}){Ui.SetDarkMode(dark,false);foreach(var size in new[]{new Size(1420,900),new Size(1120,720)}){f.Size=size;Pump();Check(preview.Code.Width>=250&&preview.Code.Height>=100,"Preview usable at "+size+" theme="+dark);using(var bitmap=new Bitmap(f.Width,f.Height)){f.DrawToBitmap(bitmap,new Rectangle(Point.Empty,f.Size));bitmap.Save(Path.Combine(Path.GetDirectoryName(Assembly.GetExecutingAssembly().Location),"live-"+dark+"-"+size.Width+".png"));}}}
 Call(f,"SetCanvasFocus",true);Pump();Check(!preview.Visible,"Solo foglio hides preview with sidebar");Call(f,"SetCanvasFocus",false);Pump();Check(preview.Visible,"F8 restores preview");
 f.SetDocument(new Diagram(),null,false);f.Close();}Console.WriteLine("LIVE_PSEUDOCODE_PASS checks="+checks);return 0;}catch(Exception e){Console.WriteLine(e);return 1;}}
}}

